<!-- This file is generated by AI. -->

<!--
  「仓库」侧栏页: git 初始化 / 暂存 / 提交 / 历史入口。

  刻意保持"薄": 它只做日常的暂存与提交; 逐文件差异、历史浏览、分支切换分别在差异选项卡与
  历史对话框里 —— 那些需要大片空间, 塞进 480px 的侧栏只会都做不好。

  ⚠️ 不带 `<style>` 块 —— 类名来自全局 `styles.css`。
-->

<script module lang="ts">
  /**
   * 提交信息草稿。
   *
   * 放在**模块作用域**而不是组件状态: 侧栏切到"项目"/"场景"再切回来组件会重新挂载, 写在组件里的
   * `$state` 会连同用户刚敲的提交信息一起丢掉。模块级的普通变量不参与响应式, 正是这里要的语义。
   */
  let commitDraft = '';
</script>

<script lang="ts">
  import {
    gitCommit,
    gitDiscard,
    gitDiscardAll,
    gitInit,
    gitSetIdentity,
    gitStage,
    gitStageAll,
    gitUnstage,
    gitUnstageAll,
    type GitFileStatus,
  } from '../commands/git';
  import { openGitDiff } from '../git/diff';
  import { refreshGitStatus } from '../git/status';
  import { STATUS_CLASS } from '../git/util';
  import { middleEllipsis } from '../lib/paths';
  import { appStore } from '../state/store.svelte';
  import AppDialog from './AppDialog.svelte';
  import Button from './Button.svelte';
  import ContextMenu, { type ContextMenuItem } from './ContextMenu.svelte';
  import GitHistoryDialog from './GitHistoryDialog.svelte';
  import Input from './Input.svelte';

  /**
   * 默认 .gitignore: 只跟踪 `game/config.txt` 与 `game/scene` 下的场景文本 (含嵌套目录)。
   * 其余资源 (图片/音频/模型) 一律忽略 —— 它们进仓库只会让每次提交变成几百兆。
   */
  const DEFAULT_GITIGNORE = '*\n!game/\n!game/config.txt\n!game/scene/\n!game/scene/**/\n!game/scene/**/*.txt\n';

  const projectPath = $derived(appStore.projectPath);
  const status = $derived(appStore.gitStatus);

  let message = $state(commitDraft);
  let busy = $state(false);
  let error = $state<string | null>(null);
  let historyOpen = $state(false);
  let initOpen = $state(false);
  let gitignore = $state(DEFAULT_GITIGNORE);
  let identityOpen = $state(false);
  let identity = $state({ name: '', email: '' });
  let menu = $state<{ file: GitFileStatus; section: 'staged' | 'unstaged'; x: number; y: number } | null>(null);

  const staged = $derived(status?.staged ?? []);
  const unstaged = $derived(status?.unstaged ?? []);

  /*
   * 进入仓库页时刷新一次。
   *
   * 仓库状态平时由全局的文件监听驱动, 但"刚切到这个页面"正是用户想看到最新状态的时刻。
   */
  $effect(() => {
    const path = projectPath;
    if (!path) return;
    void refreshGitStatus(path);
  });

  /** 跑一次 git 操作: 统一处理 busy / 报错 / 操作后刷新状态。 */
  async function run(action: () => Promise<unknown>): Promise<boolean> {
    const path = projectPath;
    if (!path || busy) return false;
    busy = true;
    error = null;
    try {
      await action();
      await refreshGitStatus(path);
      return true;
    } catch (e) {
      error = String(e);
      return false;
    } finally {
      busy = false;
    }
  }

  function updateDraft(value: string): void {
    commitDraft = value;
    message = value;
  }

  async function commit(): Promise<void> {
    const text = message.trim();
    const path = projectPath;
    if (!text || !path) return;
    const ok = await run(() => gitCommit(path, text));
    if (ok) updateDraft('');
  }

  /** 提交前的身份检查: 没配过作者就先把身份问清楚 (git 会直接拒绝这次提交)。 */
  function tryCommit(): void {
    if (!message.trim()) return;
    if (!status?.identity) {
      identity = { name: '', email: '' };
      identityOpen = true;
      return;
    }
    void commit();
  }

  async function submitIdentity(): Promise<void> {
    const path = projectPath;
    if (!path) return;
    const ok = await run(() => gitSetIdentity(path, identity.name.trim(), identity.email.trim()));
    if (ok) {
      identityOpen = false;
      void commit();
    }
  }

  function discardAll(): void {
    const path = projectPath;
    if (!path) return;
    void run(() => gitDiscardAll(path));
  }

  function openMenu(event: MouseEvent, file: GitFileStatus, section: 'staged' | 'unstaged'): void {
    event.preventDefault();
    menu = { file, section, x: event.clientX, y: event.clientY };
  }

  /*
   * 文件行的右键菜单。
   *
   * 标签与动作一致: 已暂存区的两项做的是 `git unstage` (取消暂存), 不是丢弃内容 —— 写成"放弃"
   * 既危险又说不清自己做了什么。
   */
  const menuItems = $derived.by<ContextMenuItem[]>(() => {
    /*
     * 先取到局部常量再分支: `menu` 是 `$state`, 在回调里读它时 TypeScript 无法保持"已经排除了
     * null"的判断, 于是每一处都要 `!` 或断言。
     */
    const current = menu;
    const path = projectPath;
    if (!current || !path) return [];

    if (current.section === 'staged') {
      /*
       * 已暂存区**只有取消动作**: 在这里给"暂存全部"没有意义 —— 已经在暂存区里的文件不需要
       * 再暂存一次, 而"把工作区的其它改动也加进来"是仓库整体操作, 属于下方的"暂存全部"按钮。
       */
      return [
        {
          key: 'unstage-one',
          label: '取消暂存',
          iconName: 'ArrowUndo',
          onClick: () => void run(() => gitUnstage(path, [current.file.path])),
        },
        {
          key: 'unstage-all',
          label: '取消全部暂存',
          iconName: 'ArrowUndo',
          onClick: () => void run(() => gitUnstageAll(path)),
        },
      ];
    }

    return [
      /*
       * 读的动作放在最前面, 与编辑器里"查看差异"的惯用位置一致; 它下面是会改仓库状态的动作,
       * 中间用一条分隔线断开。
       */
      {
        key: 'diff-vs-staged',
        // 左侧是"暂存项里那一份", 右侧是"磁盘上现在这一份" —— 也就是**还没暂存的那部分**
        label: '与暂存项比较',
        iconName: 'ArrowSwap',
        onClick: () => openGitDiff(current.file.path, 'index-to-worktree'),
      },
      { key: 'separator-diff', separator: true },
      {
        key: 'stage-one',
        label: '暂存',
        iconName: 'Add',
        onClick: () => void run(() => gitStage(path, [current.file.path])),
      },
      {
        key: 'stage-all',
        label: '暂存全部',
        iconName: 'SelectAllOn',
        onClick: () => void run(() => gitStageAll(path)),
      },
      { key: 'separator-discard', separator: true },
      {
        key: 'discard-one',
        // 未暂存区这一项才是真丢弃, 因此文案写"放弃"
        label: '放弃',
        iconName: 'ArrowUndo',
        danger: true,
        onClick: () => void run(() => gitDiscard(path, [current.file.path])),
      },
      {
        key: 'discard-all',
        label: '放弃全部',
        iconName: 'ArrowUndo',
        danger: true,
        onClick: discardAll,
      },
    ];
  });
</script>

{#if !projectPath}
  <div class="repository empty">未打开项目</div>
{:else if !status}
  <div class="repository empty">加载中…</div>
{:else if !status.initialized}
  <div class="repository">
    <div class="repository-init">
      <p>Git 是版本管理工具，可以保存项目的每次历史版本，方便随时回顾或恢复到之前的某个状态。</p>
      <p>初始化后，只需「暂存 → 提交」两步，就能把当前的修改保存为一个历史记录。</p>
      <Button
        appearance="primary"
        icon="BranchFork"
        disabled={busy}
        onclick={() => {
          gitignore = DEFAULT_GITIGNORE;
          initOpen = true;
        }}
      >
        初始化仓库
      </Button>
    </div>

    {#if initOpen}
      <AppDialog title="初始化仓库" size="medium" height={440} onClose={() => (initOpen = false)}>
        <p class="confirm-message">
          初始化将在项目目录创建 git 仓库。默认只跟踪场景文本文件，其余资源 (图片/音频等) 会被忽略。 如需调整可编辑下方
          .gitignore 内容：
        </p>
        <textarea class="gitignore-editor dialog-scroll" bind:value={gitignore} disabled={busy}></textarea>
        {#if error}
          <p class="prompt-error">{error}</p>
        {/if}

        {#snippet footer()}
          <Button disabled={busy} onclick={() => (initOpen = false)}>取消</Button>
          <Button
            appearance="primary"
            disabled={busy}
            onclick={() =>
              void run(async () => {
                await gitInit(projectPath, gitignore);
                initOpen = false;
              })}
          >
            初始化
          </Button>
        {/snippet}
      </AppDialog>
    {/if}
  </div>
{:else}
  <div class="repository">
    <div class="repository-commit">
      <!--
        提交信息框用原生 textarea, 高度交给 `.commit-editor` 的 min/max-height —— 超出内部滚动。
      -->
      <textarea
        class="commit-editor ui-input"
        placeholder="描述本次提交的内容…"
        value={message}
        disabled={busy}
        oninput={(event) => updateDraft(event.currentTarget.value)}></textarea>

      <!--
        三个按钮并排靠左, 用既有的 `.git-actions` (一行按钮) 而不是四列网格的
        `.repository-commit-actions` —— 后者会把"查看历史"顶到最右边。
      -->
      <div class="git-actions">
        <Button
          appearance="primary"
          icon="Checkmark"
          disabled={busy || message.trim().length === 0 || staged.length === 0}
          onclick={tryCommit}
        >
          提交
        </Button>
        <Button
          icon="Add"
          disabled={busy || unstaged.length === 0}
          onclick={() => void run(() => gitStageAll(projectPath))}
        >
          暂存全部
        </Button>
        <Button icon="History" disabled={busy} onclick={() => (historyOpen = true)}>查看历史</Button>
      </div>
    </div>

    <div class="repository-lists">
      <div class="repository-section">
        <div class="repository-section-title">暂存项 ({staged.length})</div>
        {#if staged.length === 0}
          <div class="muted repository-empty-list">暂无已暂存的更改</div>
        {:else}
          {#each staged as file (file.path)}
            <button
              type="button"
              class="git-file-item"
              title={file.path}
              onclick={() => openGitDiff(file.path, 'staged')}
              oncontextmenu={(event) => openMenu(event, file, 'staged')}
            >
              <span class="git-file-status {STATUS_CLASS[file.status] ?? ''}">{file.status}</span>
              <span class="git-file-name">{middleEllipsis(file.path, 40)}</span>
              <span class="git-file-stats">
                {#if file.additions > 0}<em class="git-add">+{file.additions}</em>{/if}
                {#if file.deletions > 0}<em class="git-del">-{file.deletions}</em>{/if}
              </span>
            </button>
          {/each}
        {/if}
      </div>

      <div class="repository-section">
        <div class="repository-section-title">更改项 ({unstaged.length})</div>
        {#if unstaged.length === 0}
          <div class="muted repository-empty-list">工作区没有更改</div>
        {:else}
          {#each unstaged as file (file.path)}
            <button
              type="button"
              class="git-file-item"
              title={file.path}
              onclick={() => openGitDiff(file.path, 'unstaged')}
              oncontextmenu={(event) => openMenu(event, file, 'unstaged')}
            >
              <span class="git-file-status {STATUS_CLASS[file.status] ?? ''}">{file.status}</span>
              <span class="git-file-name">{middleEllipsis(file.path, 40)}</span>
              <span class="git-file-stats">
                {#if file.additions > 0}<em class="git-add">+{file.additions}</em>{/if}
                {#if file.deletions > 0}<em class="git-del">-{file.deletions}</em>{/if}
              </span>
            </button>
          {/each}
        {/if}
      </div>
    </div>

    {#if menu}
      <ContextMenu x={menu.x} y={menu.y} items={menuItems} onClose={() => (menu = null)} />
    {/if}

    {#if identityOpen}
      <AppDialog title="设置提交身份" size="form" height={360} onClose={() => (identityOpen = false)}>
        <p class="confirm-message">首次提交需要填写作者姓名和邮箱，将写入此项目的 git 配置。</p>
        <div class="prompt-field">
          <span class="settings-label">姓名</span>
          <Input bind:value={identity.name} placeholder="你的名字" disabled={busy} />
        </div>
        <div class="prompt-field">
          <span class="settings-label">邮箱</span>
          <Input bind:value={identity.email} placeholder="you@example.com" disabled={busy} />
        </div>
        {#if error}
          <p class="prompt-error">{error}</p>
        {/if}

        {#snippet footer()}
          <Button disabled={busy} onclick={() => (identityOpen = false)}>取消</Button>
          <Button
            appearance="primary"
            disabled={busy || !identity.name.trim() || !identity.email.trim()}
            onclick={() => void submitIdentity()}
          >
            保存并提交
          </Button>
        {/snippet}
      </AppDialog>
    {/if}

    {#if historyOpen}
      <GitHistoryDialog onClose={() => (historyOpen = false)} />
    {/if}

    {#if error && !identityOpen}
      <AppDialog title="操作失败" size="small" height={220} onClose={() => (error = null)}>
        <p class="confirm-message">{error}</p>

        {#snippet footer()}
          <Button appearance="primary" onclick={() => (error = null)}>确定</Button>
        {/snippet}
      </AppDialog>
    {/if}
  </div>
{/if}
